(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12;
  const w1y = Math.cos(y*0.018-t*0.28)*18 + Math.sin(x*0.015+t*0.33)*12;
  const sx = x+w1x, sy = y+w1y;
  const w2x = Math.sin(sx*0.025-sy*0.01+t*0.5)*8;
  const w2y = Math.cos(sy*0.025+sx*0.01-t*0.45)*8;
  const fx = sx+w2x, fy = sy+w2y;
  const src = [
    [140+Math.sin(t*0.5)*120, 70+Math.cos(t*0.35)*50, 0.075, 2.1, 1.0],
    [340+Math.cos(t*0.45)*110, 170+Math.sin(t*0.6)*55, 0.09, 1.8, 0.85],
    [240+Math.sin(t*0.28+2)*150, 110+Math.cos(t*0.42+1)*95, 0.055, 2.5, 1.1],
    [100+Math.cos(t*0.7+1)*90, 190+Math.sin(t*0.55+3)*65, 0.11, 1.4, 0.9],
    [380+Math.sin(t*0.38+4)*100, 55+Math.cos(t*0.8+2)*75, 0.065, 2.8, 1.05],
    [200+Math.cos(t*0.32+5)*130, 210+Math.sin(t*0.48)*85, 0.085, 2.0, 0.95],
    [300+Math.sin(t*0.6+3)*80, 30+Math.cos(t*0.5+4)*60, 0.1, 1.6, 1.15],
    [60+Math.cos(t*0.4+6)*70, 130+Math.sin(t*0.65+2)*70, 0.07, 2.3, 0.88]
  ];
  let aS=0, iS=0, cS=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((fx-sX)**2+(fy-sY)**2);
    const wave=Math.sin(d*f-t*sp);
    const ring=Math.exp(-d*0.003)*0.4;
    aS+=wave*w;
    iS+=Math.sin(d*f*0.65+t*sp*0.55+1.7)*w;
    cS+=Math.sin(d*f*1.3-t*sp*0.8+2.5)*w*ring;
  }
  const act=aS/8, inh=iS/8, cross=cS/8;
  const bg=(Math.sin(fx*0.035+fy*0.022+t*0.75)+Math.sin(fx*0.028-fy*0.038+t*1.05))/2
    +Math.sin((fx+fy)*0.11+t*2.3)*0.2+Math.sin((fx-fy)*0.09-t*1.8)*0.2
    +Math.sin(fx*0.06*fy*0.06+t*0.4)*0.15;
  const dist=Math.sqrt((fx-cx)**2+(fy-cy)**2), ang=Math.atan2(fy-cy,fx-cx);
  const spiral=(Math.sin(dist*0.045-ang*3.5-t*1.4)+Math.sin(dist*0.035+ang*4.5-t*1.1))*0.35;
  const spiral2=(Math.sin(dist*0.08+ang*2-t*2.2)*0.5+Math.sin(dist*0.06-ang*5+t*1.8)*0.5)*0.2;
  const micro=Math.sin(fx*0.22)*Math.sin(fy*0.22)*Math.sin((fx+fy)*0.15+t*0.7)*0.3;
  const reaction=Math.tanh((act-inh*0.65+bg*0.25+spiral+spiral2+cross*0.8+micro)*2.0);
  const cell=Math.tanh((Math.sin(fx*0.13)*Math.sin(fy*0.13)+Math.sin((fx+fy)*0.09+t)*0.5+Math.sin(fx*0.07-fy*0.11+t*0.6)*0.3)*1.4)*0.25;
  const detail=Math.sin(fx*0.3+t*1.2)*Math.sin(fy*0.25-t*0.9)*0.1;
  const blend=reaction*0.65+cell*0.2+detail*0.15, v=blend*0.5+0.5;
  const pal=[
    [5,12,55],[10,45,95],[15,90,115],[25,140,130],[60,170,120],
    [140,185,80],[200,175,55],[215,135,60],[195,90,65],[150,55,70],
    [90,30,60],[45,18,52],[15,10,48],[5,12,55]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.82+Math.sin(reaction*Math.PI)*0.18;
  const edge=Math.abs(reaction)>0.65?1.12:Math.abs(reaction)>0.85?1.2:1.0;
  const glow=Math.max(0,reaction)*0.15;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*60)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*40)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*80)|0
  ];
}
